const raw = $json.text ?? $json.response ?? $json.output ?? JSON.stringify($json);
let evaluation;
try { evaluation = JSON.parse(raw); } catch { throw new Error('LiteLLM returned invalid JSON'); }
const required = ['decision', 'topic', 'event_key', 'score', 'score_breakdown', 'reason', 'quality_flags', 'key_facts', 'factual_caveats'];
for (const field of required) if (!(field in evaluation)) throw new Error(`Missing required field: ${field}`);
if (!['Individual', 'Queue', 'Discard'].includes(evaluation.decision)) throw new Error('Invalid decision');
const parts = evaluation.score_breakdown;
const sum = parts.audience_interest + parts.narrative_potential + parts.curiosity + parts.timeliness + parts.reliability;
if (!Number.isInteger(evaluation.score) || evaluation.score !== sum) throw new Error('Score does not match breakdown');
return [{ json: { ...$node['Preparar entrada segura'].json, evaluation, raw_response: evaluation } }];
